#define main legacy_main
#include "jaccard-cuda/main.cu"
#undef main
#include <set>
const int N=64;
template<bool weighted>void pipeline(int e,int*p,int*i,float*v,float*work,float*wi,float*ws,float*wj){dim3 b((e+255)/256),t(256);fill<weighted,float><<<b,t>>>(e,wj,1.f);fill<false,float><<<b,t>>>(e,wi,0.f);jaccard_row_sum<weighted,float><<<dim3(1,(N+3)/4),dim3(16,4)>>>(N,p,i,wj,work);jaccard_is_opt<weighted,float><<<dim3(1,1,(N+7)/8),dim3(8,4,8)>>>(N,e,p,i,wj,work,wi,ws);jaccard_jw<weighted,float><<<b,t>>>(e,v,.46f,wi,ws,wj);}
int main(){vector<int>p{0},ind;vector<float>v;vector<set<int>>sets(N);for(int row=0;row<N;row++){for(int col=0;col<N;col++)if((col-row+N)%N<17+row%15){ind.push_back(col);v.push_back(1+(3*row+col)%9);sets[row].insert(col);}p.push_back(ind.size());}int e=ind.size(),*P,*I;float*V,*W,*WI,*WS,*WJ;cudaMalloc(&P,(N+1)*4);cudaMalloc(&I,e*4);cudaMalloc(&V,e*4);cudaMalloc(&W,N*4);cudaMalloc(&WI,e*4);cudaMalloc(&WS,e*4);cudaMalloc(&WJ,e*4);cudaMemcpy(P,p.data(),(N+1)*4,cudaMemcpyHostToDevice);cudaMemcpy(I,ind.data(),e*4,cudaMemcpyHostToDevice);cudaMemcpy(V,v.data(),e*4,cudaMemcpyHostToDevice);vector<vector<float>>wants;for(bool weighted:{true,false}){vector<double>rw(N),ii(e),ss(e),jj(e);for(int row=0;row<N;row++)for(int c:sets[row])rw[row]+=weighted?double(c+1)/e:1.;for(int row=0;row<N;row++)for(int j=p[row];j<p[row+1];j++){int col=ind[j];for(int c:sets[row])if(sets[col].count(c))ii[j]+=weighted?double(c+1)/e:1.;ss[j]=rw[row]+rw[col];jj[j]=double(.46f)*v[j]*ii[j]/(ss[j]-ii[j]);}vector<float>o;o.insert(o.end(),rw.begin(),rw.end());o.insert(o.end(),ii.begin(),ii.end());o.insert(o.end(),ss.begin(),ss.end());o.insert(o.end(),jj.begin(),jj.end());wants.push_back(o);}pipeline<true>(e,P,I,V,W,WI,WS,WJ);pipeline<false>(e,P,I,V,W,WI,WS,WJ);cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){double total=0;vector<float>out,want;for(int mode=0;mode<2;mode++){cudaDeviceSynchronize();auto start=chrono::steady_clock::now();for(int k=0;k<10;k++)if(mode==0)pipeline<true>(e,P,I,V,W,WI,WS,WJ);else pipeline<false>(e,P,I,V,W,WI,WS,WJ);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;total+=chrono::duration<double>(chrono::steady_clock::now()-start).count()/10;vector<float>data(N+3*e);cudaMemcpy(data.data(),W,N*4,cudaMemcpyDeviceToHost);cudaMemcpy(data.data()+N,WI,e*4,cudaMemcpyDeviceToHost);cudaMemcpy(data.data()+N+e,WS,e*4,cudaMemcpyDeviceToHost);cudaMemcpy(data.data()+N+2*e,WJ,e*4,cudaMemcpyDeviceToHost);out.insert(out.end(),data.begin(),data.end());want.insert(want.end(),wants[mode].begin(),wants[mode].end());}bool ok=true;double err=0;for(size_t i=0;i<out.size();i++){err=max(err,double(fabs(out[i]-want[i])));ok=ok&&isfinite(out[i])&&fabs(out[i]-want[i])<=1e-5f+numeric_limits<float>::epsilon()*fabs(want[i]);}char path[64];snprintf(path,64,"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(out.data(),4,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.15g,\"timing_region\":\"sum_weighted_unweighted_fivekernel_pipeline_means\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,ok?"true":"false",out.size(),err,path,out.size());if(!ok)return 1;}cudaFree(P);cudaFree(I);cudaFree(V);cudaFree(W);cudaFree(WI);cudaFree(WS);cudaFree(WJ);}
